auto [matches, near_misses] =
    scan_directory(root, plugins, options.ast_cache, resolution.warnings);

if (!matches.empty()) {
    matches = remove_superseded(matches, options.ast_cache);
}

if (matches.empty()) {
    // Only keep near-misses if this is the final level and nothing matched at all.
    // They are diagnostic information for explaining why detection failed.
    if (level == levels) {
        // Sort by priority descending; show the highest-scoring would-bes first.
        std::sort(near_misses.begin(), near_misses.end(),
                  [](const NearMiss& left, const NearMiss& right) {
                      return left.priority > right.priority;
                  });
        // Keep only the top 3 near-misses to avoid overwhelming output.
